import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"en/changelog.md","lastUpdated":null}'),n={name:"changelog.md"};function r(d,e,l,c,s,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_1-4-0-2026-08-25" tabindex="-1">1.4.0 (2026-08-25) <a class="header-anchor" href="#_1-4-0-2026-08-25" aria-label="Permalink to &quot;1.4.0 (2026-08-25)&quot;">​</a></h2><p>Merge behavior has changed. A per locale <code>themeConfig</code> now overrides the shared one instead of losing to it, and <code>themeConfig</code> arrays such as <code>nav</code> are replaced by the more specific value instead of being merged entry by entry. Sites that relied on the previous order may see different output.</p><ul><li>Add <code>notFound</code> page and <code>skipToContentLabel</code> translations for every language</li><li>Allow either the directory path or the language code as the key of the per language options (<code>label</code>, <code>link</code>, <code>lang</code>, <code>title</code>, <code>titleTemplate</code>, <code>description</code>, <code>head</code>, <code>themeConfig</code>)</li><li>Fix <code>withI18n</code> writing into the shared translation constants, which crashed the next call with <code>TypeError</code> and could take down the dev server</li><li>Fix search translations not being applied when the provider is set through <code>themeConfig</code> (#9)</li><li>Fix a per locale <code>themeConfig</code> being overwritten by the shared one</li><li>Fix <code>themeConfig</code> arrays gaining <code>null</code> entries when both sides mixed value types</li><li>Fix the shared <code>head</code> being copied into every locale, which duplicated <code>link</code>, <code>script</code> and <code>style</code> tags on every page</li><li>Fix <code>titleTemplate</code> being dropped when set to <code>false</code></li><li>Fix <code>withI18n</code> writing back into the two options objects passed to it</li><li>Reject a <code>rootLocale</code> that is missing from <code>locales</code>, and two locales resolving to the same key</li><li>Report the format error instead of a <code>TypeError</code> for a malformed <code>locales</code> entry</li><li>Remove the hardcoded GitHub name from the chinese simplified, spanish and portuguese <code>editLink</code> texts</li><li>Fix mistranslated german, italian, vietnamese, indonesian, spanish, portuguese, japanese and chinese traditional strings</li><li>Resolve supported locales through a lookup map instead of repeated linear scans</li></ul><h2 id="_1-3-5-2025-12-18" tabindex="-1">1.3.5 (2025-12-18) <a class="header-anchor" href="#_1-3-5-2025-12-18" aria-label="Permalink to &quot;1.3.5 (2025-12-18)&quot;">​</a></h2><ul><li>Fix search box does not work when themeConfig search provider is set (#9)</li></ul><h2 id="_1-3-4-2025-04-26" tabindex="-1">1.3.4 (2025-04-26) <a class="header-anchor" href="#_1-3-4-2025-04-26" aria-label="Permalink to &quot;1.3.4 (2025-04-26)&quot;">​</a></h2><ul><li>Fixed some common themeConfig settings not being merged (#8)</li></ul><h2 id="_1-3-3-2025-03-13" tabindex="-1">1.3.3 (2025-03-13) <a class="header-anchor" href="#_1-3-3-2025-03-13" aria-label="Permalink to &quot;1.3.3 (2025-03-13)&quot;">​</a></h2><ul><li>Do not include in the options when <code>editLink</code> is not defined (#6)</li></ul><h2 id="_1-3-2-2024-12-07" tabindex="-1">1.3.2 (2024-12-07) <a class="header-anchor" href="#_1-3-2-2024-12-07" aria-label="Permalink to &quot;1.3.2 (2024-12-07)&quot;">​</a></h2><ul><li>Update french translations (@paul-louyot)</li></ul><h2 id="_1-3-1-2024-12-07" tabindex="-1">1.3.1 (2024-12-07) <a class="header-anchor" href="#_1-3-1-2024-12-07" aria-label="Permalink to &quot;1.3.1 (2024-12-07)&quot;">​</a></h2><ul><li>Fix import of type declaration files</li></ul><h2 id="_1-3-0-2024-10-24" tabindex="-1">1.3.0 (2024-10-24) <a class="header-anchor" href="#_1-3-0-2024-10-24" aria-label="Permalink to &quot;1.3.0 (2024-10-24)&quot;">​</a></h2><ul><li><strong>BREAKING CHANGES</strong>: There have been significant changes to how this plugin is used. Learn more by visiting the following documentation pages: <a href="https://vitepress-i18n.cdget.com" target="_blank" rel="noreferrer">https://vitepress-i18n.cdget.com</a></li></ul><h2 id="_1-2-0-2024-10-24" tabindex="-1">1.2.0 (2024-10-24) <a class="header-anchor" href="#_1-2-0-2024-10-24" aria-label="Permalink to &quot;1.2.0 (2024-10-24)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li><strong>BREAKING CHANGES</strong>: The <code>generateI18nLocale</code> and <code>generateI18nSearch</code> functions have now been merged into <code>withI18n</code>. Therefore, both functions will be removed in the next version. Please refer to the documentation to migrate to the <code>withI18n</code> function.</li></ul><h2 id="_1-1-1-2024-10-23" tabindex="-1">1.1.1 (2024-10-23) <a class="header-anchor" href="#_1-1-1-2024-10-23" aria-label="Permalink to &quot;1.1.1 (2024-10-23)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li>Fix chinese simplified string (#1)</li></ul><h2 id="_1-1-0-2024-10-23" tabindex="-1">1.1.0 (2024-10-23) <a class="header-anchor" href="#_1-1-0-2024-10-23" aria-label="Permalink to &quot;1.1.0 (2024-10-23)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li><strong>BREAKING CHANGES</strong>: The <code>generateI18nLocale</code> and <code>generateI18nSearch</code> functions have now been merged into <code>generateI18n</code>. Therefore, both functions will be removed in the next version. Please refer to the documentation to migrate to the <code>generateI18n</code> function.</li></ul><h2 id="_1-0-6-2024-09-16" tabindex="-1">1.0.6 (2024-09-16) <a class="header-anchor" href="#_1-0-6-2024-09-16" aria-label="Permalink to &quot;1.0.6 (2024-09-16)&quot;">​</a></h2><p>This version is deprecated and not recommended for production use.</p><ul><li>Override <code>editLinkPattern</code> value even if defined common theme configs</li><li>Add <code>debugPrint</code> option for <code>generateI18nSearch</code></li></ul><h2 id="_1-0-5-2024-09-16-not-for-production" tabindex="-1">1.0.5 (2024-09-16) - Not for Production <a class="header-anchor" href="#_1-0-5-2024-09-16-not-for-production" aria-label="Permalink to &quot;1.0.5 (2024-09-16) - Not for Production&quot;">​</a></h2><ul><li>Add italian translations</li><li>Allow auto set lang and label value when if not defined</li><li>Add <code>debugPrint</code> method</li><li>Add <code>disableAutoSetLangValue</code> method</li></ul><h2 id="_1-0-4-2024-09-07-not-for-production" tabindex="-1">1.0.4 (2024-09-07) - Not for Production <a class="header-anchor" href="#_1-0-4-2024-09-07-not-for-production" aria-label="Permalink to &quot;1.0.4 (2024-09-07) - Not for Production&quot;">​</a></h2><ul><li>Fix import issue</li></ul><h2 id="_1-0-3-2024-09-07-not-for-production" tabindex="-1">1.0.3 (2024-09-07) - Not for Production <a class="header-anchor" href="#_1-0-3-2024-09-07-not-for-production" aria-label="Permalink to &quot;1.0.3 (2024-09-07) - Not for Production&quot;">​</a></h2><ul><li>Add chinese traditional, japanese, spanish, portuguese, russian, indonesian, german, french, vietnamese translations</li><li>Split translation and type files</li></ul><h2 id="_1-0-2-2024-09-06-not-for-production" tabindex="-1">1.0.2 (2024-09-06) - Not for Production <a class="header-anchor" href="#_1-0-2-2024-09-06-not-for-production" aria-label="Permalink to &quot;1.0.2 (2024-09-06) - Not for Production&quot;">​</a></h2><ul><li>Add chinese simplified translation</li></ul><h2 id="_1-0-1-2024-09-04-not-for-production" tabindex="-1">1.0.1 (2024-09-04) - Not for Production <a class="header-anchor" href="#_1-0-1-2024-09-04-not-for-production" aria-label="Permalink to &quot;1.0.1 (2024-09-04) - Not for Production&quot;">​</a></h2><ul><li>Minor improvements</li></ul><h2 id="_1-0-0-2024-09-04-not-for-production" tabindex="-1">1.0.0 (2024-09-04) - Not for Production <a class="header-anchor" href="#_1-0-0-2024-09-04-not-for-production" aria-label="Permalink to &quot;1.0.0 (2024-09-04) - Not for Production&quot;">​</a></h2><p>Not purpose for release. Do not use production.</p><ul><li>Initial release</li></ul>',41)])])}const f=o(n,[["render",r]]);export{p as __pageData,f as default};
